import{_ as e,o as a,c as i,a2 as d}from"./chunks/framework.GbRRgL9t.js";const k=JSON.parse('{"title":"API 概览与鉴权","description":"","frontmatter":{},"headers":[],"relativePath":"api/overview.md","filePath":"api/overview.md","lastUpdated":1789902237000}'),s={name:"api/overview.md"};function o(r,t,l,h,n,c){return a(),i("div",null,[...t[0]||(t[0]=[d('<h1 id="api-概览与鉴权" tabindex="-1">API 概览与鉴权 <a class="header-anchor" href="#api-概览与鉴权" aria-label="Permalink to &quot;API 概览与鉴权&quot;">​</a></h1><p>本文档描述 CircleChat 后端的 HTTP API 与 WebSocket 协议。所有接口请求到服务根路径下的 <code>/api/...</code>。</p><h2 id="基础约定" tabindex="-1">基础约定 <a class="header-anchor" href="#基础约定" aria-label="Permalink to &quot;基础约定&quot;">​</a></h2><ul><li><strong>Base URL</strong>：取决于部署形态，由 <code>config.js</code> 的 <code>apiBase</code> 决定（同源部署为 <code>/</code>，反代子路径为 <code>/chat</code>，跨域为完整域名）。</li><li><strong>内容类型</strong>：JSON 接口的请求体与响应均为 <code>application/json</code>。</li><li><strong>Cookie</strong>：登录成功后在 <code>HttpOnly</code> Cookie <code>circlechat_token</code> 中下发会话令牌，前端所有请求带 <code>credentials: &#39;same-origin&#39;</code>。</li></ul><h2 id="响应格式" tabindex="-1">响应格式 <a class="header-anchor" href="#响应格式" aria-label="Permalink to &quot;响应格式&quot;">​</a></h2><p>绝大多数 JSON 接口返回统一结构：</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;ok&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#B31D28;--shiki-light-font-style:italic;--shiki-dark:#FDAEB7;--shiki-dark-font-style:italic;">...</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span></code></pre></div><p>失败时返回：</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;ok&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;error&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;i18n.key 或可读文本&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span></code></pre></div><p><code>error</code> 字段多为前端 i18n 键或中文提示，供展示用。</p><h2 id="鉴权方式" tabindex="-1">鉴权方式 <a class="header-anchor" href="#鉴权方式" aria-label="Permalink to &quot;鉴权方式&quot;">​</a></h2><ul><li><strong>公开接口</strong>：<code>register</code>、<code>login</code>、<code>health</code>、<code>setup</code>、<code>twofa/verify</code> 不需要登录。</li><li><strong>已登录接口</strong>：除公开接口外，其余接口均要求携带有效会话 Cookie。</li><li><strong>管理接口</strong>：<code>/api/admin/...</code> 额外要求<strong>管理员权限</strong>，非管理员访问返回 <code>403</code>。</li><li><strong>两步验证（2FA）</strong>：若账号开启了 TOTP，登录只返回 <code>{ ok, need2fa: true, challenge }</code>，需调用 <code>POST /api/twofa/verify</code> 验证后才建立会话。</li></ul><h2 id="登录限速" tabindex="-1">登录限速 <a class="header-anchor" href="#登录限速" aria-label="Permalink to &quot;登录限速&quot;">​</a></h2><p>同 IP 连续失败 5 次后锁定 10 分钟，期间登录返回 <code>429</code>（<code>api.login.rateLimited</code>）。</p><h2 id="http-状态码速查" tabindex="-1">HTTP 状态码速查 <a class="header-anchor" href="#http-状态码速查" aria-label="Permalink to &quot;HTTP 状态码速查&quot;">​</a></h2><table tabindex="0"><thead><tr><th>状态码</th><th>含义</th></tr></thead><tbody><tr><td><code>200</code></td><td>成功</td></tr><tr><td><code>400</code></td><td>参数不合法 / 请求体过大</td></tr><tr><td><code>401</code></td><td>未登录或凭据错误</td></tr><tr><td><code>403</code></td><td>无权限（未激活、被封禁、非管理员、无法查看该房间）</td></tr><tr><td><code>404</code></td><td>资源不存在 / 分片会话失效</td></tr><tr><td><code>409</code></td><td>冲突（如用户名已被占用）</td></tr><tr><td><code>413</code></td><td>请求体 / 上传文件超限</td></tr><tr><td><code>429</code></td><td>触发登录限速</td></tr></tbody></table><h2 id="上传与-websocket" tabindex="-1">上传与 WebSocket <a class="header-anchor" href="#上传与-websocket" aria-label="Permalink to &quot;上传与 WebSocket&quot;">​</a></h2><ul><li>文件上传（单次与分片）属于特殊接口，见<a href="./messages.html">消息与上传</a>。</li><li>实时消息、在线状态、正在输入、表情回应、撤回、处罚推送均走 WebSocket，见<a href="./websocket.html">WebSocket 协议</a>。</li></ul><h2 id="接口分类总览" tabindex="-1">接口分类总览 <a class="header-anchor" href="#接口分类总览" aria-label="Permalink to &quot;接口分类总览&quot;">​</a></h2><table tabindex="0"><thead><tr><th>章节</th><th>覆盖接口</th></tr></thead><tbody><tr><td><a href="./auth.html">认证与登录</a></td><td>register / login / logout / health / setup / twofa</td></tr><tr><td><a href="./account.html">账号与资料</a></td><td>me / penalties / pass / profile / settings</td></tr><tr><td><a href="./friends.html">好友与用户</a></td><td>users / friends / profile / report</td></tr><tr><td><a href="./groups.html">群组</a></td><td>groups 系列</td></tr><tr><td><a href="./messages.html">消息与上传</a></td><td>messages / upload 系列</td></tr><tr><td><a href="./mailbox.html">站内信箱</a></td><td>announcements / notifications</td></tr><tr><td><a href="./admin.html">管理端 API</a></td><td>admin 系列</td></tr></tbody></table>',20)])])}const g=e(s,[["render",o]]);export{k as __pageData,g as default};
